CREATE OR REPLACE VIEW public."vAggregationAvg5m"
 AS
 SELECT ed."HardwareId",
    date_bin('00:05:00'::interval, ed."ReceivedTs", '2001-01-01 00:00:00'::timestamp without time zone) AS date_bin,
    avg(ed."Payload"::double precision) AS value
   FROM "EventData" ed
     JOIN "Component" co ON co."HardwareId"::text = ed."HardwareId"::text
  WHERE (co."Type"::text = ANY (ARRAY['FI'::character varying::text, 'SE'::character varying::text])) AND co."Removed" = false
  GROUP BY ed."HardwareId", (date_bin('00:05:00'::interval, ed."ReceivedTs", '2001-01-01 00:00:00'::timestamp without time zone));

ALTER TABLE public."vAggregationAvg5m"
    OWNER TO postgres;

GRANT ALL ON TABLE public."vAggregationAvg5m" TO postgres;
GRANT SELECT ON TABLE public."vAggregationAvg5m" TO sensql;


CREATE OR REPLACE VIEW public."vAggregationSum5m"
    AS
     SELECT ed."HardwareId",
    date_bin('00:05:00'::interval, ed."ReceivedTs", '2001-01-01 00:00:00'::timestamp without time zone) AS date_bin,
    sum(ed."Payload"::double precision) / (count(*)::double precision / 5::double precision) AS value,
    count(*) AS cnt
   FROM "EventData" ed
     JOIN "Component" co ON co."HardwareId"::text = ed."HardwareId"::text
  WHERE (co."Type"::text = ANY (ARRAY['AC'::character varying::text, 'SW'::character varying::text])) AND co."Removed" = false
  GROUP BY ed."HardwareId", (date_bin('00:05:00'::interval, ed."ReceivedTs", '2001-01-01 00:00:00'::timestamp without time zone));

ALTER TABLE public."vAggregationSum5m"
    OWNER TO postgres;

GRANT ALL ON TABLE public."vAggregationSum5m" TO postgres;
GRANT SELECT ON TABLE public."vAggregationSum5m" TO sensql;


CREATE OR REPLACE VIEW public."vAggregationSum1d"
    AS
     SELECT "HardwareId",
    date_bin('24:00:00'::interval, date_bin, '2001-01-01 00:00:00'::timestamp without time zone) AS date_bin,
    sum(value) AS value
   FROM "vAggregationSum5m" ed
  GROUP BY "HardwareId", (date_bin('24:00:00'::interval, date_bin, '2001-01-01 00:00:00'::timestamp without time zone));

