  WHERE (co."Type"::text = ANY (ARRAY['FI'::character varying::text, 'CO'::character varying::text, 'SE'::character varying::text])) AND co."Removed" = false
  GROUP BY ed."HardwareId", (date_bin('01:00:00'::interval, ed."ReceivedTs", '2001-01-01 00:00:00'::timestamp without time zone));

