CREATE OR REPLACE VIEW public."vEventDataExport"
 AS
 SELECT DISTINCT s1."DisplayName" AS "StationName",
    s1."Uid" AS "StationUid",
    c1."DisplayName" AS "ComponentName",
    c1."HardwareId",
    c1."Type" AS "ComponentType",
    ed1.date_bin AS "Received",
    c1."DisplayUnit" AS "Unit",
    ed1.value AS "Value"
   FROM "vAggregationAvg5m" ed1
     JOIN "Component" c1 ON c1."HardwareId"::text = ed1."HardwareId"::text
     JOIN "Station" s1 ON s1."Id" = c1."StationId"
UNION
 SELECT DISTINCT s2."DisplayName" AS "StationName",
    s2."Uid" AS "StationUid",
    c2."DisplayName" AS "ComponentName",
    c2."HardwareId",
    c2."Type" AS "ComponentType",
    ed2.date_bin AS "Received",
    c2."DisplayUnit" AS "Unit",
    ed2.value AS "Value"
   FROM "vAggregationSum5m" ed2
     JOIN "Component" c2 ON c2."HardwareId"::text = ed2."HardwareId"::text
     JOIN "Station" s2 ON s2."Id" = c2."StationId";

