GRANT SELECT ON TABLE public."vEventDataExport" TO sensql;


CREATE OR REPLACE VIEW public."vComponentLast"
    AS
     SELECT cm."DisplayName",
    cm."ShortName",
    cm."HardwareId",
    cm."Type",
    cm."StationId",
    cm."MinValue",
    cm."MaxValue",
    cm."DisplayUnit",
    cm."DisplayOrder",
    cm."AdjustmentFunction",
    y."LastPayload",
    y."LastReceivedTs",
    y."FirstReceivedTs"
   FROM ( SELECT "vEventDataLast"."HardwareId",
            "vEventDataLast"."LastPayload",
            "vEventDataLast"."LastReceivedTs",
            "vEventDataLast"."FirstReceivedTs"
           FROM "vEventDataLast"
        UNION
         SELECT cc."HardwareId",
            NULL::character varying AS "LastPayload",
            NULL::timestamp without time zone AS "LastReceivedTs",
            NULL::timestamp without time zone AS "FirstReceivedTs"
           FROM "Component" cc
          WHERE NOT (cc."HardwareId"::text IN ( SELECT DISTINCT "EventData"."HardwareId"
                   FROM "EventData"))) y
     JOIN "Component" cm ON cm."HardwareId"::text = y."HardwareId"::text
  WHERE cm."Removed" = false AND cm."Visible" = true
UNION
 SELECT cn."DisplayName",
    cn."ShortName",
    concat(cn."HardwareId", '#')::character varying(36) AS "HardwareId",
    'CO'::character varying AS "Type",
    cm."StationId",
    0 AS "MinValue",
    999999999 AS "MaxValue",
    cn."DisplayUnit",
    cn."DisplayOrder",
    cn."AdjustmentFunction",
    cn."Count"::text AS "LastPayload",
    cn."LastTs" AS "LastReceivedTs",
    NULL::timestamp without time zone AS "FirstReceivedTs"
   FROM "Counter" cn
     JOIN "Component" cm ON cn."HardwareId"::text = cm."HardwareId"::text
  WHERE cm."Removed" = false AND cm."Visible" = true;

ALTER TABLE public."vComponentLast"
    OWNER TO postgres;

GRANT ALL ON TABLE public."vComponentLast" TO postgres;
GRANT SELECT ON TABLE public."vComponentLast" TO sensql;


CREATE OR REPLACE VIEW public."vAlert"
 AS
 SELECT aa."Id",
    aa."StationUid",
    st."ShortName" AS "StationShortName",
    aa."FirstEventTs",
    aa."LastEventTs",
    aa."ConfirmedAt",
    aa."ConfirmedBy",
    aa."IsActive",
    aa."MailSendAt",
    y."Faults"
   FROM ( SELECT x."Id",
            string_agg(cc."DisplayName"::text, ', '::text) AS "Faults"
           FROM ( SELECT DISTINCT ed."HardwareId",
                    a."Id"
                   FROM "vEventData" ed
                     JOIN "vComponentLast" c ON c."HardwareId"::text = ed."HardwareId"::text AND c."Type"::text = 'FL'::text AND ed."Payload"::text <> '0'::text
                     JOIN "Alert" a ON a."StationUid"::text = ed."StationUid"::text
                  WHERE ed."ReceivedTs" >= a."FirstEventTs" AND ed."ReceivedTs" <= a."LastEventTs") x
             JOIN "Component" cc ON x."HardwareId"::text = cc."HardwareId"::text
          GROUP BY x."Id") y
     JOIN "Alert" aa ON aa."Id" = y."Id"
     JOIN "Station" st ON st."Uid"::text = aa."StationUid"::text;

ALTER TABLE public."vAlert"
    OWNER TO postgres;

GRANT ALL ON TABLE public."vAlert" TO postgres;
GRANT SELECT ON TABLE public."vAlert" TO sensql;


CREATE OR REPLACE VIEW public."vStation"
    AS
     SELECT "Id",
    "DisplayName",
    "ShortName",
    "Latitude",
    "Longitude",
    "Type",
    "DisplayColor",
    "Uid",
    "DisplayOrder",
    "AlertReceiverEmailAddresses",
    "WatchdogHardwareId",
    "MaintenanceActiveSinceTs",
    COALESCE(( SELECT true
           FROM "Alert" a_1
          WHERE a_1."StationUid"::text = s."Uid"::text AND a_1."ConfirmedAt"::text IS NULL AND a_1."IsActive"::text = 'Y'::text), false) AS "HasActiveAlert"
   FROM "Station" s
  WHERE "Visible" = true;

ALTER TABLE public."vStation"
    OWNER TO postgres;

GRANT ALL ON TABLE public."vStation" TO postgres;
GRANT SELECT ON TABLE public."vStation" TO sensql;

END;